import selfies as sf
from rdkit import Chem
parts=['[C][C][Branch1][C][C][S][=Branch1][C][=O][=Branch1][C][=O][N][C][C][Branch1][C][C][Branch1][C][O][C][=C][C][=C][Branch1][C][N][C][=C][Ring1][#Branch1]','[O][=C][Branch1][C][Cl][C][=C][C][=C][C][=C][Ring1][=Branch1]','[C][C][C][O][C][Ring1][Branch1]','[C][C][N][Branch1][Ring1][C][C][C][C]','[O]']
for i,p in enumerate(parts):
    try:
        smi=sf.decoder(p)
        m=Chem.MolFromSmiles(smi)
        print(i, smi, Chem.MolToSmiles(m) if m else None)
    except Exception as e: print(i,type(e).__name__,e)
